207	\begin{tabular}{l cc}
208	\toprule
209	Strategy & NER F1 & RE F1 \\
210	\midrule
211	Random   & 0.608 & 0.354 \\
212	Greedy   & 0.644 & \bmark{0.404} \\
213	\midrule
